  const activeJob = state?.jobs.find(job => job.id === selectedResult?.jobId || (activeRun && job.pipelineRunId === activeRun.id));
  const fit = (nodes = definition.nodes) => { const el = canvasRef.current; if (!el || !nodes.length) return; const minX = Math.min(...nodes.map(node => node.position.x)), minY = Math.min(...nodes.map(node => node.position.y)); const width = Math.max(...nodes.map(node => node.position.x + NODE_W)) - minX, height = Math.max(...nodes.map(node => node.position.y + NODE_H)) - minY; const scale = Math.min(1, Math.max(.28, Math.min((el.clientWidth - 100) / width, (el.clientHeight - 150) / height))); setView({ x: (el.clientWidth - width * scale) / 2 - minX * scale, y: Math.max(70, (el.clientHeight - height * scale) / 2 - minY * scale - 20), scale }); };
  useEffect(() => { if (!state || initialized.current) return; initialized.current = true; const def = recipes[0] ? clone(recipes[0]) : makeTemplate('writing', state); setDraft(def); setSelectedId(def.nodes.find(node => node.type !== 'input')?.id || def.nodes[0]?.id || ''); setDirty(!recipes.length); requestAnimationFrame(() => fit(def.nodes)); }, [state]);
